/***********************************************************************
 *    Locking discipline:
 *      SpinLock protects ALL in-memory data structures (hash, LRU, dirty
 *      list, buffer flags, refcounts).  Disk I/O (ReadDeviceSector/
 *      WriteDeviceSector) is ALWAYS performed OUTSIDE the lock.
 *
 *      Typical three-phase pattern:
 *        Phase 1 (locked):   find/alloc buffer, mark IO_BUSY, refcount++.
 *        Phase 2 (unlocked): perform disk I/O.
 *        Phase 3 (locked):   clear IO_BUSY, refcount--, insert into hash/LRU/dirty.
 ***********************************************************************/

#include "StdAfx.h"
#include "blkcache.h"
#include "KAPI.H"
#include <stdio.h>

 /* ==================================================================
  *  Forward declarations ！ internal helpers
  * ================================================================== */

static __BLK_BUF_HEAD* __HashLookup(__BLK_CACHE* pCache, __SECTOR_T SectorNum);
static VOID            __HashInsert(__BLK_CACHE* pCache, __BLK_BUF_HEAD* pBuf);
static VOID            __HashRemove(__BLK_CACHE* pCache, __BLK_BUF_HEAD* pBuf);

static VOID __LruInit(__BLK_BUF_HEAD* pSentinel);
static VOID __LruRemove(__BLK_BUF_HEAD* pBuf);
static VOID __LruAddHead(__BLK_BUF_HEAD* pSentinel, __BLK_BUF_HEAD* pBuf);
static VOID __LruAddTail(__BLK_BUF_HEAD* pSentinel, __BLK_BUF_HEAD* pBuf);

static VOID __DirtyInit(__BLK_BUF_HEAD* pSentinel);
static VOID __DirtyAdd(__BLK_BUF_HEAD* pSentinel, __BLK_BUF_HEAD* pBuf);
static VOID __DirtyRemove(__BLK_BUF_HEAD* pBuf);
static BOOL __DirtyIsEmpty(__BLK_BUF_HEAD* pSentinel);

static __BLK_BUF_HEAD* __GetFreeBuffer(__BLK_CACHE* pCache, DWORD dwLockFlags);
static BOOL __ReadFromDisk(__DEVICE_OBJECT* pDev, __SECTOR_T Sector, BYTE* pBuf);
static BOOL __WriteToDisk(__DEVICE_OBJECT* pDev, __SECTOR_T Sector,
	DWORD SectorCount, BYTE* pBuf);
static DWORD __BlkCacheFlushThreadRoutine(LPVOID lpParam);

/* ==================================================================
 *  Lock macros ！ use SMP-safe versions; they become no-ops on UP.
 * ================================================================== */

#define CACHE_LOCK(pCache, dwFlags)   \
    __ENTER_CRITICAL_SECTION_SMP((pCache)->SpinLock, dwFlags)

#define CACHE_UNLOCK(pCache, dwFlags) \
    __LEAVE_CRITICAL_SECTION_SMP((pCache)->SpinLock, dwFlags)

 /* ==================================================================
  *  Hash table  (protected by SpinLock ！ called only while locked)
  * ================================================================== */

static __forceinline DWORD __HashFn(__SECTOR_T SectorNum)
{
#if defined(_M_AMD64) || defined(_M_X64) || defined(__x86_64__)
	DWORD folded = (DWORD)(SectorNum ^ (SectorNum >> 32));
	return folded & BLK_CACHE_HASH_MASK;
#else
	return (DWORD)SectorNum & BLK_CACHE_HASH_MASK;
#endif
}

static __BLK_BUF_HEAD* __HashLookup(__BLK_CACHE* pCache, __SECTOR_T SectorNum)
{
	__BLK_BUF_HEAD* pBuf = pCache->pHashBuckets[__HashFn(SectorNum)];
	while (pBuf != NULL)
	{
		if (pBuf->SectorNum == SectorNum)
			return pBuf;
		pBuf = pBuf->pHashNext;
	}
	return NULL;
}

static VOID __HashInsert(__BLK_CACHE* pCache, __BLK_BUF_HEAD* pBuf)
{
	DWORD idx = __HashFn(pBuf->SectorNum);
	pBuf->pHashNext = pCache->pHashBuckets[idx];
	pCache->pHashBuckets[idx] = pBuf;
}

static VOID __HashRemove(__BLK_CACHE* pCache, __BLK_BUF_HEAD* pBuf)
{
	DWORD idx = __HashFn(pBuf->SectorNum);
	__BLK_BUF_HEAD** ppIndirect = &pCache->pHashBuckets[idx];
	while (*ppIndirect != NULL)
	{
		if (*ppIndirect == pBuf)
		{
			*ppIndirect = pBuf->pHashNext;
			pBuf->pHashNext = NULL;
			return;
		}
		ppIndirect = &(*ppIndirect)->pHashNext;
	}
}

/* ==================================================================
 *  LRU list  (protected by SpinLock ！ called only while locked)
 *
 *  Sentinel convention: empty list ★ sentinel.pLruNext == sentinel.pLruPrev == &sentinel
 *  Head = sentinel.pLruNext  (most-recently-used)
 *  Tail = sentinel.pLruPrev  (least-recently-used)
 * ================================================================== */

static VOID __LruInit(__BLK_BUF_HEAD* pSentinel)
{
	pSentinel->pLruNext = pSentinel;
	pSentinel->pLruPrev = pSentinel;
}

static VOID __LruRemove(__BLK_BUF_HEAD* pBuf)
{
	pBuf->pLruPrev->pLruNext = pBuf->pLruNext;
	pBuf->pLruNext->pLruPrev = pBuf->pLruPrev;
	pBuf->pLruNext = pBuf;
	pBuf->pLruPrev = pBuf;
}

static VOID __LruAddHead(__BLK_BUF_HEAD* pSentinel, __BLK_BUF_HEAD* pBuf)
{
	pBuf->pLruNext = pSentinel->pLruNext;
	pBuf->pLruPrev = pSentinel;
	pSentinel->pLruNext->pLruPrev = pBuf;
	pSentinel->pLruNext = pBuf;
}

static VOID __LruAddTail(__BLK_BUF_HEAD* pSentinel, __BLK_BUF_HEAD* pBuf)
{
	pBuf->pLruPrev = pSentinel->pLruPrev;
	pBuf->pLruNext = pSentinel;
	pSentinel->pLruPrev->pLruNext = pBuf;
	pSentinel->pLruPrev = pBuf;
}

/* ==================================================================
 *  Dirty list  (protected by SpinLock ！ called only while locked)
 * ================================================================== */

static VOID __DirtyInit(__BLK_BUF_HEAD* pSentinel)
{
	pSentinel->pDirtyNext = pSentinel;
	pSentinel->pDirtyPrev = pSentinel;
}

static VOID __DirtyAdd(__BLK_BUF_HEAD* pSentinel, __BLK_BUF_HEAD* pBuf)
{
	__BLK_BUF_HEAD* pTail = pSentinel->pDirtyPrev;
	pBuf->pDirtyPrev = pTail;
	pBuf->pDirtyNext = pSentinel;
	pTail->pDirtyNext = pBuf;
	pSentinel->pDirtyPrev = pBuf;
}

static VOID __DirtyRemove(__BLK_BUF_HEAD* pBuf)
{
	pBuf->pDirtyPrev->pDirtyNext = pBuf->pDirtyNext;
	pBuf->pDirtyNext->pDirtyPrev = pBuf->pDirtyPrev;
	pBuf->pDirtyNext = pBuf;
	pBuf->pDirtyPrev = pBuf;
}

static BOOL __DirtyIsEmpty(__BLK_BUF_HEAD* pSentinel)
{
	return (pSentinel->pDirtyNext == pSentinel);
}

/* ==================================================================
 *  Low-level disk I/O  (called OUTSIDE spinlock)
 *
 *  These mirror the DRCB pattern from FATMGR2.C exactly.
 * ================================================================== */

static BOOL __ReadFromDisk(__DEVICE_OBJECT* pDev, __SECTOR_T Sector, BYTE* pBuf)
{
	__DRIVER_OBJECT* pDrvObject;
	__DRCB*          pDrcb = NULL;
	DWORD            dwStartSector;
	BOOL             bResult = FALSE;

	BUG_ON((NULL == pDev) || (NULL == pBuf));

	pDrvObject = pDev->lpDriverObject;
	BUG_ON(NULL == pDrvObject);

	BUG_ON(DEVICE_OBJECT_SIGNATURE != pDev->dwSignature);

	pDrcb = (__DRCB*)ObjectManager.CreateObject(&ObjectManager, NULL, OBJECT_TYPE_DRCB);
	if (NULL == pDrcb)
		return FALSE;
	if (!pDrcb->Initialize((__COMMON_OBJECT*)pDrcb))
		goto __TERMINAL;

	dwStartSector = (DWORD)Sector;

	pDrcb->dwStatus = DRCB_STATUS_INITIALIZED;
	pDrcb->dwRequestMode = DRCB_REQUEST_MODE_IOCTRL;
	pDrcb->dwCtrlCommand = IOCONTROL_READ_SECTOR;
	pDrcb->dwInputLen = sizeof(DWORD);
	pDrcb->lpInputBuffer = (LPVOID)&dwStartSector;
	pDrcb->dwOutputLen = pDev->dwBlockSize;
	pDrcb->lpOutputBuffer = pBuf;

	if (0 == pDrvObject->DeviceCtrl((__COMMON_OBJECT*)pDrvObject,
		(__COMMON_OBJECT*)pDev, pDrcb))
		goto __TERMINAL;

	bResult = TRUE;

__TERMINAL:
	if (pDrcb)
		ObjectManager.DestroyObject(&ObjectManager,
		(__COMMON_OBJECT*)pDrcb);
	return bResult;
}

static BOOL __WriteToDisk(__DEVICE_OBJECT* pDev, __SECTOR_T Sector,
	DWORD SectorCount, BYTE* pBuf)
{
	__DRIVER_OBJECT*    pDrvObject;
	__DRCB*             pDrcb = NULL;
	__SECTOR_INPUT_INFO ssi;
	BOOL                bResult = FALSE;

	BUG_ON((NULL == pDev) || (0 == SectorCount) || (NULL == pBuf));

	pDrvObject = pDev->lpDriverObject;
	BUG_ON(NULL == pDrvObject);

	pDrcb = (__DRCB*)ObjectManager.CreateObject(&ObjectManager, NULL, OBJECT_TYPE_DRCB);
	if (NULL == pDrcb)
		return FALSE;
	if (!pDrcb->Initialize((__COMMON_OBJECT*)pDrcb))
		goto __TERMINAL;

	ssi.dwStartSector = (DWORD)Sector;
	ssi.dwBufferLen = SectorCount * pDev->dwBlockSize;
	ssi.lpBuffer = pBuf;

	pDrcb->dwStatus = DRCB_STATUS_INITIALIZED;
	pDrcb->dwRequestMode = DRCB_REQUEST_MODE_IOCTRL;
	pDrcb->dwCtrlCommand = IOCONTROL_WRITE_SECTOR;
	pDrcb->dwInputLen = sizeof(__SECTOR_INPUT_INFO);
	pDrcb->lpInputBuffer = (LPVOID)&ssi;
	pDrcb->dwOutputLen = 0;
	pDrcb->lpOutputBuffer = NULL;

	if (0 == pDrvObject->DeviceCtrl((__COMMON_OBJECT*)pDrvObject,
		(__COMMON_OBJECT*)pDev, pDrcb))
		goto __TERMINAL;

	bResult = TRUE;

__TERMINAL:
	if (pDrcb)
		ObjectManager.DestroyObject(&ObjectManager,
		(__COMMON_OBJECT*)pDrcb);
	return bResult;
}

/* ==================================================================
 *  Buffer allocator  (protected by SpinLock or mutex when called)
 *
 *  Finds a free (clean, unbusy, refcount==0) buffer.  If the only
 *  candidates are dirty, flushes the LRU-most one outside the lock
 *  via the three-phase protocol.
 * ================================================================== */

static __BLK_BUF_HEAD* __GetFreeBuffer(__BLK_CACHE* pCache, DWORD dwLockFlags)
{
	__BLK_BUF_HEAD* pBuf;
	__BLK_BUF_HEAD* pDirtyCandidate;
	DWORD           dwLoopCount;

	/*
	 * Pass 1: look for a completely clean buffer (flags == 0 or VALID without
	 * DIRTY/BUSY, refcount == 0).
	 */
	for (dwLoopCount = 0; dwLoopCount < pCache->dwAllocated; dwLoopCount++)
	{
		pBuf = pCache->LruSentinel.pLruPrev;  /* LRU tail */

		if (pBuf == &pCache->LruSentinel)
		{
			/* should not happen if dwAllocated > 0 */
			break;  
		}

		if (0 == pBuf->dwRefCount && !(pBuf->dwFlags & BLK_BUF_BUSY_MASK))
		{
			if (!(pBuf->dwFlags & BLK_BUF_DIRTY))
			{
				/* Clean ！ use immediately. */
				if (pBuf->dwFlags & BLK_BUF_VALID)
					__HashRemove(pCache, pBuf);
				__LruRemove(pBuf);
				pBuf->dwFlags = 0;
				return pBuf;
			}
		}

		/* Move to head so we don't keep revisiting the same buffer. */
		__LruRemove(pBuf);
		__LruAddHead(&pCache->LruSentinel, pBuf);
	}

	/*
	 * Pass 2: find a dirty buffer with refcount==0 and no I/O in flight
	 * to flush and reclaim.
	 */
	pDirtyCandidate = NULL;
	pBuf = pCache->LruSentinel.pLruPrev;
	while (pBuf != &pCache->LruSentinel)
	{
		if (0 == pBuf->dwRefCount &&
			!(pBuf->dwFlags & BLK_BUF_BUSY_MASK) &&
			(pBuf->dwFlags & BLK_BUF_DIRTY))
		{
			pDirtyCandidate = pBuf;
			break;
		}
		pBuf = pBuf->pLruPrev;
	}

	if (NULL == pDirtyCandidate)
	{
		_hx_printf("[%s]no dirty candidate buff.\r\n", __func__);
		return NULL;  /* every buffer is pinned or busy */
	}

	/*
	 * Phase 1 (locked): tag the buffer, remove from hash/LRU/dirty.
	 */
	pBuf = pDirtyCandidate;
	//pBuf->dwFlags |= BLK_BUF_FLUSHING;
	pBuf->dwFlags = 0;
	pBuf->dwRefCount++;
	__HashRemove(pCache, pBuf);
	__LruRemove(pBuf);
	__DirtyRemove(pBuf);

	/*
	 * Phase 2 (unlocked): flush to disk.
	 */
	//CACHE_UNLOCK(pCache, dwLockFlags);

	pBuf->bIoResult = __WriteToDisk(pCache->pDevice, pBuf->SectorNum,
		1, pBuf->pData);

	//CACHE_LOCK(pCache, dwLockFlags);

	/*
	 * Phase 3 (locked): cleanup.
	 */
	pBuf->dwFlags &= ~(BLK_BUF_DIRTY | BLK_BUF_FLUSHING);
	pBuf->dwRefCount--;

	if (pBuf->bIoResult)
		pCache->dwWriteBackCount++;

	/*
	 * If another thread grabbed this buffer for the SAME sector while we
	 * were writing, it's been re-inserted into the hash.  Otherwise the
	 * buffer is now clean and reusable.  We set flags=0 and return it.
	 */
	if (0 == pBuf->dwRefCount && !(pBuf->dwFlags & BLK_BUF_VALID))
	{
		pBuf->dwFlags = 0;
		return pBuf;
	}

	/*
	 * The buffer was re-claimed by a concurrent reader while we flushed.
	 * Try again from the top.  This is extremely rare.
	 * Issue Debug: 
	 * execute path sames reach here, lead the LRU list empty, since LRU
	 * remove and dirty remove are called, but with the NULL buff
	 * returned to users.
	 */
	_hx_printf("[%s]buffer is re-clamimed by others.\r\n", __func__);
	return NULL;
}

/* ==================================================================
 *  BlkCacheCreate
 * ================================================================== */

__BLK_CACHE* BlkCacheCreate(__DEVICE_OBJECT* pDevice, DWORD dwMaxBufs,
	DWORD dwReadAheadNum)
{
	__BLK_CACHE* pCache = NULL;
	DWORD        i = 0;
	DWORD        dwTotalSize = 0;

	BUG_ON(NULL == pDevice);

	pCache = (__BLK_CACHE*)KMemAlloc(sizeof(__BLK_CACHE), KMEM_SIZE_TYPE_ANY);
	if (NULL == pCache)
		return NULL;
	memset(pCache, 0, sizeof(__BLK_CACHE));

	pCache->pDevice = pDevice;
	pCache->dwBlockSize = pDevice->dwBlockSize;
	pCache->dwFlushIntervalMs = BLK_CACHE_FLUSH_INTERVAL;

	if (0 == dwMaxBufs)
		dwMaxBufs = BLK_CACHE_DEFAULT_MAX;
	pCache->dwMaxBuffers = dwMaxBufs;

	if (0 == dwReadAheadNum)
	{
		pCache->dwReadAheadNum = BLK_CACHE_READAHEAD;
	}
	else {
		pCache->dwReadAheadNum = dwReadAheadNum;
	}

	/* Init hash table. */
	for (i = 0; i < BLK_CACHE_HASH_SIZE; i++)
		pCache->pHashBuckets[i] = NULL;

	/* Init sentinels. */
	__LruInit(&pCache->LruSentinel);
	__DirtyInit(&pCache->DirtySentinel);

	/* Init spinlock. */
	__INIT_SPIN_LOCK(pCache->SpinLock, "blkcache");

	/* Create mutex object. */
	pCache->mutex = (__MUTEX*)CreateMutex();
	if (NULL == pCache)
	{
		/* Can not continue. */
		_hx_printf("[%s]failed to create mutex.\r\n", __func__);
		KMemFree(pCache, KMEM_SIZE_TYPE_ANY, 0);
		return NULL;
	}

	/* Allocate buffer pool as one contiguous block. */
	dwTotalSize = dwMaxBufs * BLK_BUF_TOTAL_SIZE(pDevice->dwBlockSize);
	pCache->pBufPool = (__BLK_BUF_HEAD*)KMemAlloc(dwTotalSize, KMEM_SIZE_TYPE_ANY);
	if (NULL == pCache->pBufPool)
	{
		_hx_printf("[%s]Create buffer pool failed.\r\n", __func__);
		KMemFree(pCache, KMEM_SIZE_TYPE_ANY, 0);
		return NULL;
	}
	memset(pCache->pBufPool, 0, dwTotalSize);

	/* Set up each buffer: pData pointer, owner, add to LRU. */
	for (i = 0; i < dwMaxBufs; i++)
	{
		__BLK_BUF_HEAD* pBuf = (__BLK_BUF_HEAD*)(
			(BYTE*)pCache->pBufPool + i * BLK_BUF_TOTAL_SIZE(pDevice->dwBlockSize));

		pBuf->pData = (BYTE*)pBuf + BLK_BUF_HEAD_SIZE;
		pBuf->pOwner = pCache;
		__LruAddHead(&pCache->LruSentinel, pBuf);
	}
	pCache->dwAllocated = dwMaxBufs;

	/* Start background flush thread. */
	pCache->bFlushThreadStop = FALSE;
	pCache->bFlushThreadExited = FALSE;

	pCache->hFlushThread = (__KERNEL_THREAD_OBJECT*)CreateKernelThread(
		0,                                  /* dwStackSize: default               */
		KERNEL_THREAD_STATUS_READY,         /* dwInitStatus: run immediately      */
		PRIORITY_LEVEL_LOW,                 /* dwPriority: low-priority background */
		__BlkCacheFlushThreadRoutine,       /* lpStartRoutine                     */
		(LPVOID)pCache,                     /* lpRoutineParam                     */
		NULL,                               /* lpReserved                         */
		"blkflush"                          /* lpszName                           */
	);
	/* If thread creation fails, cache still works ！ dirty buffers are
	 * flushed on eviction and by explicit BlkCacheFlushRange calls. */
	if (NULL == pCache->hFlushThread)
	{
		_hx_printf("[%s]flush thread created failed but cache still works.\r\n",
			__func__);
	}

	return pCache;
}

/* ==================================================================
 *  BlkCacheDestroy
 *  Process of the destroying(wrote by manual):
 *  1. Set a flag tell the background thread to exit;
 *  2. The background thread see the flag, set another flag to
 *     indicate it exit, then exit;
 *  3. The caller wait for another flag, then destroy the kernel
 *     thread object. Otherwise will call terminate kernel thread
 *     API to kill the background thread brutely;
 *  4. The routine collects all dirty blocks and flush them into
 *     disk(Acquire lock and operate list, write);
 *  5. Then frees all buffer objects and the cache object.
 *  
 *  So there is a bug(or exclusive condition): When collect dirty
 *  buffers, the routine checks buffer's flags, only if the BUSY
 *  flag is not set, it then remove it from dirty list and link into
 *  flushing list. If there is buffer with BUSY flag set, then the
 *  buffer will not be collected and will not be released. But at
 *  the end of routine, all buffers and cache management object are
 *  released! So if the buffer object with BUSY set is used by other
 *  thread, it will lead crash!
 *  A feasible solution is try the collect and write back process
 *  several times, untill all buffers' flag are set with out BUSY.
 *  Should implement it later.
 * ================================================================== */

VOID BlkCacheDestroy(__BLK_CACHE* pCache)
{
	DWORD           dwFlags;
	__BLK_BUF_HEAD* pBuf;
	__BLK_BUF_HEAD* pFlushList;

	if (NULL == pCache)
		return;

	/*
	 * Step 1: signal the background thread to stop.
	 * It will see the flag after its current sleep expires.
	 */
	pCache->bFlushThreadStop = TRUE;

	if (pCache->hFlushThread != NULL)
	{
		DWORD dwWaitMs = pCache->dwFlushIntervalMs * 2;
		DWORD dwElapsed = 0;

		while (!pCache->bFlushThreadExited && dwElapsed < dwWaitMs)
		{
			KernelThreadManager.Sleep(
				(__COMMON_OBJECT*)&KernelThreadManager, 100);
			dwElapsed += 100;
		}

		if (!pCache->bFlushThreadExited)
		{
			KernelThreadManager.TerminateKernelThread(
				(__COMMON_OBJECT*)&KernelThreadManager,
				(__COMMON_OBJECT*)pCache->hFlushThread, 0);
		}

		KernelThreadManager.DestroyKernelThread(
			(__COMMON_OBJECT*)&KernelThreadManager,
			(__COMMON_OBJECT*)pCache->hFlushThread);
		pCache->hFlushThread = NULL;
	}

	/*
	 * Step 2: final flush of all dirty buffers (three-phase).
	 */
	CACHE_LOCK(pCache, dwFlags);

	/* Collect all dirty buffers. */
	pFlushList = NULL;
	pBuf = pCache->DirtySentinel.pDirtyNext;
	while (pBuf != &pCache->DirtySentinel)
	{
		__BLK_BUF_HEAD* pNext = pBuf->pDirtyNext;

		if (!(pBuf->dwFlags & BLK_BUF_IO_BUSY))
		{
			pBuf->dwFlags |= BLK_BUF_FLUSHING;
			pBuf->dwRefCount++;
			__DirtyRemove(pBuf);
			pBuf->pBatchNext = pFlushList;
			pFlushList = pBuf;
		}

		pBuf = pNext;
	}

	CACHE_UNLOCK(pCache, dwFlags);

	/* Write them all to disk (no lock). */
	pBuf = pFlushList;
	while (pBuf != NULL)
	{
		pBuf->bIoResult = __WriteToDisk(pCache->pDevice, pBuf->SectorNum,
			1, pBuf->pData);
		if (pBuf->bIoResult)
			pCache->dwWriteBackCount++;
		pBuf = pBuf->pBatchNext;
	}

	/* Step 3: free buffer pool and cache object. */
	if (pCache->pBufPool != NULL)
	{
		KMemFree(pCache->pBufPool, KMEM_SIZE_TYPE_ANY, 0);
		pCache->pBufPool = NULL;
	}

	KMemFree(pCache, KMEM_SIZE_TYPE_ANY, 0);
}

/* ==================================================================
 *  BlkCacheRead
 *
 *  Three-phase per sector:
 *    1 (locked)   : hash lookup; hit->memcpy & done; miss->alloc buf, mark IO_BUSY
 *    2 (unlocked) : ReadDeviceSector
 *    3 (locked)   : clear IO_BUSY, mark VALID, insert hash/LRU, memcpy to user
 * ================================================================== */

DWORD BlkCacheRead(
	__BLK_CACHE*    pCache,
	__SECTOR_T      dwStartSector,
	DWORD           dwSectorNum,
	BYTE*           pBuffer)
{
	DWORD           dwFlags = 0;
	DWORD           i;
	DWORD           dwBytesPerSector;
	__SECTOR_T      Sector;
	__BLK_BUF_HEAD* pBuf;
	BOOL            bSequential;
	unsigned long   wait_result = 0;
	unsigned long   time_out = BLK_CACHE_IO_TIMEOUT;

	BUG_ON((NULL == pCache) || (0 == dwSectorNum) || (NULL == pBuffer));

	dwBytesPerSector = pCache->dwBlockSize;

	//CACHE_LOCK(pCache, dwFlags);
	wait_result = WaitForThisObjectEx((HANDLE)pCache->mutex, time_out, NULL);
	if (OBJECT_WAIT_RESOURCE != wait_result)
	{
		_hx_printf("[%s]wait failed with ret[%d]\r\n",
			__func__, wait_result);
		return 0;
	}

	/* Detect sequential access for read-ahead. */
	bSequential = (dwStartSector == pCache->LastReadEndSector);
	pCache->LastReadEndSector = dwStartSector + dwSectorNum;

	for (i = 0; i < dwSectorNum; i++)
	{
		Sector = dwStartSector + (__SECTOR_T)i;

		/* ---- Phase 1: lookup ---- */
		pBuf = __HashLookup(pCache, Sector);

		if (pBuf != NULL && (pBuf->dwFlags & BLK_BUF_VALID) &&
			!(pBuf->dwFlags & BLK_BUF_IO_BUSY))
		{
			/* Cache hit ！ copy to user buffer. */
			memcpy(pBuffer + i * dwBytesPerSector, pBuf->pData, dwBytesPerSector);
			__LruRemove(pBuf);
			__LruAddHead(&pCache->LruSentinel, pBuf);
			pCache->dwHitCount++;
			continue;
		}

		/*
		 * TODO: If buffer is in process of I/O(with
		 * IO_BUSY flag set), should wait for it over,
		 * then commit access.
		 */

		/* Cache miss ！ allocate a free buffer. */
		pCache->dwMissCount++;

		do {
			pBuf = __GetFreeBuffer(pCache, dwFlags);
		} while (NULL == pBuf);   /* FIXME: add timeout in production */

		/* Mark IO_BUSY and pin before releasing lock. */
		pBuf->dwFlags = BLK_BUF_IO_BUSY;
		pBuf->dwRefCount = 1;
		pBuf->SectorNum = Sector;

		/* ---- Phase 2: I/O outside lock ---- */
		//CACHE_UNLOCK(pCache, dwFlags);

		pBuf->bIoResult = __ReadFromDisk(pCache->pDevice, Sector, pBuf->pData);

		//CACHE_LOCK(pCache, dwFlags);

		/* ---- Phase 3: cleanup ---- */
		pBuf->dwFlags &= ~BLK_BUF_IO_BUSY;
		if (pBuf->bIoResult)
			pBuf->dwFlags |= BLK_BUF_VALID;
		pBuf->dwRefCount--;

		if (pBuf->bIoResult)
		{
			__HashInsert(pCache, pBuf);
			__LruAddHead(&pCache->LruSentinel, pBuf);
			memcpy(pBuffer + i * dwBytesPerSector, pBuf->pData, dwBytesPerSector);
		}
		else
		{
			/* I/O failed ！ buffer is still clean (flags=0), return to LRU. */
			pBuf->dwFlags = 0;
			__LruAddHead(&pCache->LruSentinel, pBuf);
			//CACHE_UNLOCK(pCache, dwFlags);
			ReleaseMutex((HANDLE)pCache->mutex);
			return i * dwBytesPerSector;  /* partial read */
		}
	}

	/*
	 * Sequential read-ahead (best-effort, launched without lock).
	 */
	if (bSequential && dwSectorNum > 0)
	{
		__SECTOR_T RaSector = dwStartSector + dwSectorNum;
		DWORD      ra;

		/* Avoid walking past the end of the buffer pool. */
		for (ra = 0; ra < pCache->dwReadAheadNum; ra++)
		{
			__BLK_BUF_HEAD* pRaBuf;

			/* Quick check under lock: already cached? */
			if (__HashLookup(pCache, RaSector + ra) != NULL)
				break;

			pRaBuf = __GetFreeBuffer(pCache, dwFlags);
			if (NULL == pRaBuf)
				break;

			pRaBuf->dwFlags = BLK_BUF_IO_BUSY;
			pRaBuf->dwRefCount = 1;
			pRaBuf->SectorNum = RaSector + ra;

			//CACHE_UNLOCK(pCache, dwFlags);

			pRaBuf->bIoResult = __ReadFromDisk(pCache->pDevice,
				RaSector + ra, pRaBuf->pData);

			//CACHE_LOCK(pCache, dwFlags);

			pRaBuf->dwFlags &= ~BLK_BUF_IO_BUSY;
			if (pRaBuf->bIoResult)
				pRaBuf->dwFlags |= BLK_BUF_VALID;
			pRaBuf->dwRefCount--;

			if (pRaBuf->bIoResult)
			{
				__HashInsert(pCache, pRaBuf);
				/* tail: readahead is speculative */
				__LruAddTail(&pCache->LruSentinel, pRaBuf);  
				pCache->dwReadAheadCount++;
			}
			else
			{
				pRaBuf->dwFlags = 0;
				__LruAddHead(&pCache->LruSentinel, pRaBuf);
				break;  /* disk error ！ stop prefetching */
			}
		}
	}

	//CACHE_UNLOCK(pCache, dwFlags);
	ReleaseMutex((HANDLE)pCache->mutex);

	return dwSectorNum * dwBytesPerSector;
}

/* ==================================================================
 *  BlkCacheWrite  (write-back)
 *
 *  Three-phase per sector:
 *    1 (locked)   : hash lookup; hit★copy & mark DIRTY; miss★alloc buf, mark IO_BUSY
 *    2 (unlocked) : ReadDeviceSector (read-modify-write)
 *    3 (locked)   : clear IO_BUSY, copy user data, mark DIRTY, insert hash/dirty
 * ================================================================== */

DWORD BlkCacheWrite(
	__BLK_CACHE*    pCache,
	__SECTOR_T      dwStartSector,
	DWORD           dwSectorNum,
	const BYTE*     pBuffer)
{
	DWORD           dwFlags = 0;
	DWORD           i;
	DWORD           dwBytesPerSector;
	__SECTOR_T      Sector;
	__BLK_BUF_HEAD* pBuf;
	unsigned long   wait_result = 0;
	unsigned long   time_out = BLK_CACHE_IO_TIMEOUT;

	BUG_ON((NULL == pCache) || (0 == dwSectorNum) || (NULL == pBuffer));

	dwBytesPerSector = pCache->dwBlockSize;

	//CACHE_LOCK(pCache, dwFlags);
	wait_result = WaitForThisObjectEx((HANDLE)pCache->mutex, time_out, NULL);
	if (OBJECT_WAIT_RESOURCE != wait_result)
	{
		_hx_printf("[%s]wait failed with ret[%d]\r\n",
			__func__, wait_result);
		return 0;
	}

	for (i = 0; i < dwSectorNum; i++)
	{
		Sector = dwStartSector + (__SECTOR_T)i;

		/* ---- Phase 1: lookup ---- */
		pBuf = __HashLookup(pCache, Sector);

		if (pBuf != NULL && (pBuf->dwFlags & BLK_BUF_VALID) &&
			!(pBuf->dwFlags & BLK_BUF_IO_BUSY))
		{
			/* Cache hit ！ overwrite in memory, mark dirty. */
			memcpy(pBuf->pData, pBuffer + i * dwBytesPerSector, dwBytesPerSector);
			if (!(pBuf->dwFlags & BLK_BUF_DIRTY))
			{
				pBuf->dwFlags |= BLK_BUF_DIRTY;
				__DirtyAdd(&pCache->DirtySentinel, pBuf);
			}
			__LruRemove(pBuf);
			__LruAddHead(&pCache->LruSentinel, pBuf);
			/* Increase hit counter. */
			pCache->dwHitCount++;
			continue;
		}

		/*
		 * TODO: If the buffer could find but it's busying(
		 * with IO_BUSY flag set) now, should wait here until
		 * the buffer is flushed out, then rewrite it.
		 * Otherwise will lead conflict since a new buffer with
		 * same sector allocated later. But for now it's OK, since
		 * one mutex object is used to protect the whole cache.
		 */

		/* Cache miss ！ allocate a free buffer for read-modify-write. */
		pCache->dwMissCount++;
		do {
			pBuf = __GetFreeBuffer(pCache, dwFlags);
			/* For debugging. */
			if (NULL == pBuf)
			{
				_hx_printf("[%s]get free buffer failed, i = %d\r\n",
					__func__, i);
				/* Try again for a short while. */
				Sleep(100);
			}
		} while (NULL == pBuf);

		pBuf->dwFlags = BLK_BUF_IO_BUSY;
		pBuf->dwRefCount = 1;
		pBuf->SectorNum = Sector;

		/* ---- Phase 2: read current content from disk (outside lock) ---- */
		//CACHE_UNLOCK(pCache, dwFlags);

		/*
		 * No need to load from disk, since we will change the WHOLE
		 * sector later.
		 */
		//pBuf->bIoResult = __ReadFromDisk(pCache->pDevice, Sector, pBuf->pData);
		pBuf->bIoResult = TRUE;

		//CACHE_LOCK(pCache, dwFlags);

		/* ---- Phase 3: mark valid, copy user data, mark dirty ---- */
		pBuf->dwFlags &= ~BLK_BUF_IO_BUSY;
		if (pBuf->bIoResult)
			pBuf->dwFlags |= BLK_BUF_VALID;
		pBuf->dwRefCount--;

		if (pBuf->bIoResult)
		{
			/* Overwrite with user's new data. */
			memcpy(pBuf->pData, pBuffer + i * dwBytesPerSector, dwBytesPerSector);
			pBuf->dwFlags |= BLK_BUF_DIRTY;
			__HashInsert(pCache, pBuf);
			__DirtyAdd(&pCache->DirtySentinel, pBuf);
			__LruAddHead(&pCache->LruSentinel, pBuf);
		}
		else
		{
			/* I/O failed ！ discard buffer. */
			pBuf->dwFlags = 0;
			__LruAddHead(&pCache->LruSentinel, pBuf);
			//CACHE_UNLOCK(pCache, dwFlags);
			ReleaseMutex((HANDLE)pCache->mutex);

			return i * dwBytesPerSector;
		}
	}

	//CACHE_UNLOCK(pCache, dwFlags);
	ReleaseMutex((HANDLE)pCache->mutex);

	return dwSectorNum * dwBytesPerSector;
}

/* ==================================================================
 *  Background flush thread
 *
 *  Wakes every dwFlushIntervalMs (500 ms), collects all dirty buffers
 *  under the lock, writes them outside the lock, then cleans up.
 * ================================================================== */

static DWORD __BlkCacheFlushThreadRoutine(LPVOID lpParam)
{
	__BLK_CACHE*    pCache = (__BLK_CACHE*)lpParam;
	DWORD           dwFlags = 0;
	__BLK_BUF_HEAD* pFlushList;
	__BLK_BUF_HEAD* pBuf;
	__BLK_BUF_HEAD* pNext;

	while (TRUE)
	{
		if (pCache->bFlushThreadStop)
			break;

		KernelThreadManager.Sleep(
			(__COMMON_OBJECT*)&KernelThreadManager,
			pCache->dwFlushIntervalMs);

		/* Increment wake counter for diagnostics. */
		pCache->dwBackThreadWake++;

		if (pCache->bFlushThreadStop)
			break;

		/* ---- Phase 1: collect dirty buffers (locked) ---- */
		//CACHE_LOCK(pCache, dwFlags);
		unsigned long wait_result = WaitForThisObject((HANDLE)pCache->mutex);
		if (OBJECT_WAIT_RESOURCE != wait_result)
		{
			_hx_printf("[%s]wait failed with ret[%d]\r\n",
				__func__, wait_result);
			break;
		}

		pFlushList = NULL;
		pBuf = pCache->DirtySentinel.pDirtyNext;
		while (pBuf != &pCache->DirtySentinel)
		{
			pNext = pBuf->pDirtyNext;

			/* Skip buffers already busy with I/O or another flush. */
			if (!(pBuf->dwFlags & BLK_BUF_BUSY_MASK))
			{
				pBuf->dwFlags |= BLK_BUF_FLUSHING;
				pBuf->dwRefCount++;
				__DirtyRemove(pBuf);
				pBuf->pBatchNext = pFlushList;
				pFlushList = pBuf;
			}

			pBuf = pNext;
		}

		//CACHE_UNLOCK(pCache, dwFlags);

		/* ---- Phase 2: write to disk (unlocked) ---- */
		pBuf = pFlushList;
		while (pBuf != NULL)
		{
			pBuf->bIoResult = __WriteToDisk(pCache->pDevice, pBuf->SectorNum,
				1, pBuf->pData);
			pBuf = pBuf->pBatchNext;
		}

		/* ---- Phase 3: cleanup (locked) ---- */
		//CACHE_LOCK(pCache, dwFlags);

		pBuf = pFlushList;
		while (pBuf != NULL)
		{
			pNext = pBuf->pBatchNext;

			pBuf->dwFlags &= ~BLK_BUF_FLUSHING;
			pBuf->dwRefCount--;

			if (pBuf->bIoResult)
			{
				pBuf->dwFlags &= ~BLK_BUF_DIRTY;
				pCache->dwWriteBackCount++;
			}
			else
			{
				/* Write failed ！ re-queue for next cycle. */
				if (!(pBuf->dwFlags & BLK_BUF_DIRTY))
					pBuf->dwFlags |= BLK_BUF_DIRTY;
				__DirtyAdd(&pCache->DirtySentinel, pBuf);
			}

			pBuf = pNext;
		}

		pCache->dwBackgroundFlushCount++;

		//CACHE_UNLOCK(pCache, dwFlags);
		ReleaseMutex((HANDLE)pCache->mutex);
	}

	pCache->bFlushThreadExited = TRUE;
	return 0;
}

/* ==================================================================
 *  BlkCacheGetStats
 * ================================================================== */

VOID BlkCacheGetStats(
	__BLK_CACHE*    pCache,
	DWORD*          pHitCount,
	DWORD*          pMissCount,
	DWORD*          pDirtyCount,
	DWORD*          pBackThreadWake,
	DWORD*          pReadAhead,
	DWORD*          pWriteBack)
{
	DWORD           dirty;
	__BLK_BUF_HEAD* pBuf;

	BUG_ON(NULL == pCache);

	__ACQUIRE_SPIN_LOCK(pCache->SpinLock);

	if (pHitCount)  *pHitCount = pCache->dwHitCount;
	if (pMissCount) *pMissCount = pCache->dwMissCount;

	if (pDirtyCount)
	{
		dirty = 0;
		pBuf = pCache->DirtySentinel.pDirtyNext;
		while (pBuf != &pCache->DirtySentinel)
		{
			dirty++;
			pBuf = pBuf->pDirtyNext;
		}
		*pDirtyCount = dirty;
	}

	if (pBackThreadWake)
	{
		*pBackThreadWake = pCache->dwBackThreadWake;
	}

	if (pReadAhead)
	{
		*pReadAhead = pCache->dwReadAheadCount;
	}

	if (pWriteBack)
	{
		*pWriteBack = pCache->dwWriteBackCount;
	}

	__RELEASE_SPIN_LOCK(pCache->SpinLock);
}

/* ==================================================================
 *  BlkCacheFlushRange  ！  explicit synchronous flush
 *
 *  Three-phase:
 *    1 (locked)   : collect matching dirty buffers, mark FLUSHING, pin
 *    2 (unlocked) : __WriteToDisk for each
 *    3 (locked)   : clear FLUSHING+DIRTY, unpin; re-add to dirty on failure
 * ================================================================== */

BOOL BlkCacheFlushRange(
	__BLK_CACHE*    pCache,
	__SECTOR_T      dwStartSector,
	DWORD           dwSectorNum)
{
	DWORD           dwFlags;
	__BLK_BUF_HEAD* pFlushList;
	__BLK_BUF_HEAD* pBuf;
	__BLK_BUF_HEAD* pNext;
	__SECTOR_T      dwEndSector;
	BOOL            bAllOk = TRUE;

	if ((NULL == pCache) || (0 == dwSectorNum))
		return FALSE;

	dwEndSector = dwStartSector + (__SECTOR_T)dwSectorNum;

	/*
	 * Phase 1: collect (locked).
	 */
	CACHE_LOCK(pCache, dwFlags);

	pFlushList = NULL;
	pBuf = pCache->DirtySentinel.pDirtyNext;
	while (pBuf != &pCache->DirtySentinel)
	{
		pNext = pBuf->pDirtyNext;

		if (pBuf->SectorNum >= dwStartSector &&
			pBuf->SectorNum < dwEndSector &&
			!(pBuf->dwFlags & BLK_BUF_BUSY_MASK) &&
			(pBuf->dwFlags & BLK_BUF_DIRTY))
		{
			pBuf->dwFlags |= BLK_BUF_FLUSHING;
			pBuf->dwRefCount++;
			__DirtyRemove(pBuf);
			pBuf->pBatchNext = pFlushList;
			pFlushList = pBuf;
		}

		pBuf = pNext;
	}

	CACHE_UNLOCK(pCache, dwFlags);

	/*
	 * Phase 2: write to disk (unlocked).
	 */
	pBuf = pFlushList;
	while (pBuf != NULL)
	{
		pBuf->bIoResult = __WriteToDisk(pCache->pDevice, pBuf->SectorNum,
			1, pBuf->pData);
		if (!pBuf->bIoResult)
			bAllOk = FALSE;
		pBuf = pBuf->pBatchNext;
	}

	/*
	 * Phase 3: cleanup (locked).
	 */
	CACHE_LOCK(pCache, dwFlags);

	pBuf = pFlushList;
	while (pBuf != NULL)
	{
		pNext = pBuf->pBatchNext;

		pBuf->dwFlags &= ~BLK_BUF_FLUSHING;
		pBuf->dwRefCount--;

		if (pBuf->bIoResult)
		{
			pBuf->dwFlags &= ~BLK_BUF_DIRTY;
			pCache->dwWriteBackCount++;
		}
		else
		{
			/* Write failed ！ re-queue on dirty list for retry. */
			pBuf->dwFlags |= BLK_BUF_DIRTY;
			__DirtyAdd(&pCache->DirtySentinel, pBuf);
		}

		pBuf = pNext;
	}

	CACHE_UNLOCK(pCache, dwFlags);
	return bAllOk;
}

/* ==================================================================
 *  BlkCacheInvalidateRange
 *
 *  Drops all cached sectors in [start, start+count).  Dirty buffers
 *  in the range are flushed BEFORE being dropped (three-phase).
 * ================================================================== */

VOID BlkCacheInvalidateRange(
	__BLK_CACHE*    pCache,
	__SECTOR_T      dwStartSector,
	DWORD           dwSectorNum)
{
	DWORD           dwFlags;
	__BLK_BUF_HEAD* pFlushList;
	__BLK_BUF_HEAD* pBuf;
	__BLK_BUF_HEAD* pNext;
	__SECTOR_T      dwEndSector;
	DWORD           bucket;

	if ((NULL == pCache) || (0 == dwSectorNum))
		return;

	dwEndSector = dwStartSector + (__SECTOR_T)dwSectorNum;

	CACHE_LOCK(pCache, dwFlags);

	/*
	 * Step 1: collect dirty buffers that need flushing before invalidation.
	 * Clean buffers are invalidated immediately.
	 */
	pFlushList = NULL;

	for (bucket = 0; bucket < BLK_CACHE_HASH_SIZE; bucket++)
	{
		__BLK_BUF_HEAD** ppIndirect = &pCache->pHashBuckets[bucket];
		while (*ppIndirect != NULL)
		{
			pBuf = *ppIndirect;

			if (pBuf->SectorNum >= dwStartSector &&
				pBuf->SectorNum < dwEndSector)
			{
				if (pBuf->dwFlags & BLK_BUF_IO_BUSY)
				{
					/* I/O in flight ！ skip this buffer for now.  The caller
					 * is responsible for not invalidating sectors that have
					 * concurrent I/O in progress. */
					ppIndirect = &pBuf->pHashNext;
					continue;
				}

				if (pBuf->dwFlags & BLK_BUF_DIRTY)
				{
					/* Must flush before invalidating. */
					pBuf->dwFlags |= BLK_BUF_FLUSHING;
					pBuf->dwRefCount++;
					__DirtyRemove(pBuf);
					pBuf->pBatchNext = pFlushList;
					pFlushList = pBuf;
				}

				/* Remove from hash and LRU now. */
				*ppIndirect = pBuf->pHashNext;
				pBuf->pHashNext = NULL;
				__LruRemove(pBuf);

				if (!(pBuf->dwFlags & BLK_BUF_DIRTY))
				{
					/* Clean buffer ！ recycle directly. */
					pBuf->dwFlags = 0;
					pBuf->SectorNum = 0;
					__LruAddHead(&pCache->LruSentinel, pBuf);
				}
			}
			else
			{
				ppIndirect = &pBuf->pHashNext;
			}
		}
	}

	CACHE_UNLOCK(pCache, dwFlags);

	/*
	 * Step 2: flush dirty buffers (unlocked).
	 */
	pBuf = pFlushList;
	while (pBuf != NULL)
	{
		pBuf->bIoResult = __WriteToDisk(pCache->pDevice, pBuf->SectorNum,
			1, pBuf->pData);
		if (pBuf->bIoResult)
			pCache->dwWriteBackCount++;
		pBuf = pBuf->pBatchNext;
	}

	/*
	 * Step 3: recycle flushed buffers (locked).
	 */
	CACHE_LOCK(pCache, dwFlags);

	pBuf = pFlushList;
	while (pBuf != NULL)
	{
		pNext = pBuf->pBatchNext;

		pBuf->dwFlags &= ~(BLK_BUF_DIRTY | BLK_BUF_FLUSHING);
		pBuf->dwRefCount--;
		pBuf->dwFlags = 0;
		pBuf->SectorNum = 0;
		__LruAddHead(&pCache->LruSentinel, pBuf);

		pBuf = pNext;
	}

	CACHE_UNLOCK(pCache, dwFlags);
}
